  padding: 20px 24px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-weight: 600;
  font-size: 0.95rem;
  color: var(--gray-800);
  text-align: left;
  transition: var(--transition);
}
.faq-question:hover { color: var(--green); }

.faq-question svg {
  width: 20px;
  height: 20px;
  transition: transform 0.3s ease;
  flex-shrink: 0;
}
.faq-item.open .faq-question svg { transform: rotate(180deg); }

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease;
}

.faq-answer-inner {
  padding: 0 24px 20px;
  color: var(--gray-600);
  font-size: 0.9rem;
  line-height: 1.7;
}

/* ==================== STORE LOCATOR ==================== */
.locator-layout {
  display: grid;
  grid-template-columns: 400px 1fr;
  min-height: calc(100vh - 72px);
}

.locator-sidebar {
  background: var(--white);
