  padding: 4px;
  margin-bottom: 16px;
}

.order-type-btn {
  flex: 1;
  padding: 10px 16px;
  border-radius: 50px;
  font-weight: 600;
  font-size: 0.9rem;
  color: var(--gray-500);
  transition: var(--transition);
  text-align: center;
}
.order-type-btn.active {
  background: var(--white);
  color: var(--green);
  box-shadow: var(--shadow-sm);
}

.search-box {
  display: flex;
  gap: 8px;
}

.search-input {
  flex: 1;
  padding: 12px 16px;
  border: 2px solid var(--gray-200);
  border-radius: var(--radius-sm);
  font-size: 0.9rem;
  font-family: var(--font-body);
  transition: var(--transition);
  outline: none;
}
.search-input:focus { border-color: var(--green); }
.search-input::placeholder { color: var(--gray-400); }

.filter-btn {
  padding: 12px 16px;
  border: 2px solid var(--gray-200);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--gray-600);
  transition: var(--transition);
}
.filter-btn:hover { border-color: var(--green); color: var(--green); }
.filter-btn.active { border-color: var(--green); color: var(--green); background: #F0FFF4; }
.filter-btn svg { width: 18px; height: 18px; }

.filter-panel {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease;
}

.filter-panel.open { max-height: 300px; }

.filter-panel-inner {
  padding: 16px 0 0;
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.filter-chip {
