  color: var(--gray-600);
  transition: var(--transition);
}
.filter-chip:hover { border-color: var(--green); color: var(--green); }
.filter-chip.active { background: var(--green); color: var(--white); border-color: var(--green); }

.store-results {
  flex: 1;
  overflow-y: auto;
