  transition: var(--transition);
  cursor: pointer;
}
.store-card:hover { background: var(--cream-light); }

.store-card h3 {
  font-size: 1rem;
  font-weight: 600;
  color: var(--forest);
  margin-bottom: 4px;
}

.store-card .address {
  font-size: 0.85rem;
  color: var(--gray-500);
  margin-bottom: 8px;
}

.store-features {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  margin-bottom: 8px;
}

.store-feature {
  padding: 3px 10px;
  border-radius: 50px;
  font-size: 0.75rem;
  font-weight: 500;
  background: var(--gray-100);
  color: var(--gray-600);
}

.store-hours { font-size: 0.8rem; color: var(--gray-500); }
.store-hours strong { color: var(--green); }

.store-actions {
  display: flex;
  gap: 8px;
  margin-top: 12px;
}

.map-container {
  background: var(--gray-100);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 16px;
  color: var(--gray-400);
}

.map-placeholder {
  width: 100%;
  height: 100%;
  background: linear-gradient(135deg, #E8F5E9 0%, var(--gray-100) 50%, #E0F2F1 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 12px;
  color: var(--gray-400);
  font-size: 0.9rem;
}

.map-placeholder svg { width: 48px; height: 48px; opacity: 0.5; }

/* Map pins */
.map-pins {
  position: relative;
  width: 80%;
  height: 60%;
}

.map-pin {
  position: absolute;
  width: 32px;
  height: 32px;
  background: var(--green);
  border-radius: 50% 50% 50% 0;
  transform: rotate(-45deg);
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: var(--shadow-sm);
}
.map-pin::after {
  content: '';
  width: 10px;
  height: 10px;
  background: var(--white);
  border-radius: 50%;
  transform: rotate(45deg);
}

/* Suggestions dropdown */
.search-suggestions {
  position: absolute;
  top: 100%;
  left: 0;
  right: 0;
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-sm);
  box-shadow: var(--shadow-md);
  display: none;
  z-index: 10;
  margin-top: 4px;
}
.search-suggestions.active { display: block; }

.suggestion-item {
  padding: 12px 16px;
  font-size: 0.9rem;
  color: var(--gray-700);
  cursor: pointer;
  transition: var(--transition);
}
.suggestion-item:hover { background: var(--cream-light); }

/* ==================== FOOTER ==================== */
.site-footer {
  background: var(--forest);
  color: rgba(255,255,255,0.8);
  padding: 60px 0 0;
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 32px;
  padding-bottom: 48px;
}

.footer-col h3 {
  color: var(--white);
  font-size: 0.9rem;
  font-weight: 700;
  margin-bottom: 16px;
  letter-spacing: 0.5px;
}

.footer-col a {
  display: block;
  font-size: 0.85rem;
  color: rgba(255,255,255,0.65);
  padding: 4px 0;
  transition: var(--transition);
}
.footer-col a:hover { color: var(--cream); }

.footer-toggle { display: none; }

.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.15);
  padding: 24px 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 16px;
}

.footer-bottom-links {
  display: flex;
  gap: 24px;
}

.footer-bottom-links a {
  font-size: 0.8rem;
  color: rgba(255,255,255,0.5);
  transition: var(--transition);
}
.footer-bottom-links a:hover { color: var(--cream); }

.footer-social {
  display: flex;
  gap: 12px;
}

.social-icon {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: rgba(255,255,255,0.1);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: var(--transition);
}
.social-icon:hover { background: var(--green); }
.social-icon svg { width: 16px; height: 16px; color: var(--white); }

.footer-copyright {
  text-align: center;
  padding: 20px 0;
  font-size: 0.8rem;
  color: rgba(255,255,255,0.4);
  border-top: 1px solid rgba(255,255,255,0.08);
}

/* ==================== COOKIE BANNER ==================== */
.cookie-banner {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  background: var(--white);
  box-shadow: 0 -4px 20px rgba(0,0,0,0.15);
  z-index: 200;
  padding: 20px 0;
  transform: translateY(0);
  transition: transform 0.4s ease;
}
.cookie-banner.hidden { transform: translateY(100%); }

.cookie-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
}

.cookie-text h4 {
  font-size: 0.95rem;
  font-weight: 700;
  margin-bottom: 4px;
  color: var(--forest);
}

.cookie-text p { font-size: 0.85rem; color: var(--gray-600); }

.cookie-actions { display: flex; gap: 12px; flex-shrink: 0; }

/* ==================== TERMS ==================== */
.terms-section {
  padding: 40px 0;
  text-align: center;
}

.terms-section p {
  font-size: 0.8rem;
  color: var(--gray-500);
  max-width: 700px;
  margin: 0 auto;
  line-height: 1.7;
}

.terms-section a { color: var(--green); text-decoration: underline; }

/* ==================== RESPONSIVE ==================== */
@media (max-width: 1024px) {
  .locator-layout { grid-template-columns: 1fr; }
  .map-container { min-height: 300px; }
  .locator-sidebar { border-right: none; border-bottom: 1px solid var(--gray-200); }
  .store-results { max-height: 400px; }

  .menu-layout {
    grid-template-columns: 1fr;
  }

  .menu-sidebar {
    position: static;
    display: flex;
    overflow-x: auto;
    gap: 4px;
    padding-bottom: 16px;
    border-bottom: 1px solid var(--gray-200);
    max-height: none;
  }

  .sidebar-group { margin-bottom: 0; display: flex; gap: 4px; }
  .sidebar-group-title { display: none; }
  .sidebar-link { white-space: nowrap; }
}

@media (max-width: 768px) {
  .header-inner { height: 64px; }
  .main-nav { display: none; }
  .mobile-toggle { display: flex; }

  .main-nav.open {
    display: flex;
    flex-direction: column;
    position: absolute;
    top: 64px;
    left: 0;
    right: 0;
    background: var(--white);
    padding: 16px 24px;
    box-shadow: var(--shadow-md);
    gap: 0;
  }
  .main-nav.open a {
    padding: 12px 0;
    border-bottom: 1px solid var(--gray-100);
  }

  .hero { min-height: 400px; }
  .hero h1 { font-size: 2.4rem; }
  .hero-image { display: none; }

  .promo-grid { grid-template-columns: 1fr; }
  .promo-full { flex-direction: column; }
  .promo-card { min-height: auto; flex-direction: column; }
  .promo-card-image { flex: 0 0 auto; }

  .steps-grid { grid-template-columns: 1fr; }
  .tiers-grid { grid-template-columns: 1fr; }
  .partner-cards { grid-template-columns: 1fr; }

  .redemption-tabs { gap: 6px; }
  .redemption-tab { padding: 8px 14px; font-size: 0.82rem; }

  .gift-card { flex: 0 0 calc(50% - 10px); }

  .business-gifting-inner { flex-direction: column; }
  .business-gifting-image { flex: 0 0 auto; width: 100%; height: 200px; }

  .rewards-hero h1 { font-size: 2.2rem; }
  .gift-hero h1 { font-size: 2.2rem; }

  .footer-grid {
    grid-template-columns: 1fr;
    gap: 0;
  }

  .footer-col {
    border-bottom: 1px solid rgba(255,255,255,0.1);
  }

  .footer-col h3 {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 16px 0;
    margin-bottom: 0;
    cursor: pointer;
  }

  .footer-toggle {
    display: block;
    width: 20px;
    height: 20px;
    transition: transform 0.3s ease;
  }

  .footer-col.open .footer-toggle { transform: rotate(180deg); }

  .footer-links-wrap {
    max-height: 0;
    overflow: hidden;
    transition: max-height 0.3s ease;
  }

  .footer-col.open .footer-links-wrap { max-height: 300px; }

  .footer-links-wrap a { padding: 6px 0; }

  .footer-bottom { flex-direction: column; text-align: center; }
  .footer-bottom-links { flex-wrap: wrap; justify-content: center; }

  .cookie-inner { flex-direction: column; text-align: center; }
  .cookie-actions { width: 100%; justify-content: center; }

  .app-buttons { flex-direction: column; align-items: center; }

  .section-header h2 { font-size: 1.8rem; }
  .container { padding: 0 16px; }
}

@media (max-width: 480px) {
  .hero h1 { font-size: 2rem; }
  .gift-card { flex: 0 0 calc(100% - 10px); }
  .locator-controls { padding: 16px; }
  .store-card { padding: 16px; }
}

